async def strategy(page, ctx, log, S):
    # plan: click-cta | goal: log in | target: 🔗 Wallet MetaMask · Ronin · Solana · WalletConnect ›
    last = "no candidate"
    try: await page.wait_for_load_state("domcontentloaded", timeout=8000)
    except Exception: pass
    fr = page
    for _f in page.frames:
        if "craft.html" in (_f.url or ""):
            fr = _f
            break
    cands = [
        ("css-nth", lambda: fr.locator("button.mbtn").nth(0)),
    ]
    for how, mk in cands:
        try:
            loc = mk()
            try: await loc.scroll_into_view_if_needed(timeout=2500)
            except Exception: pass
            await loc.click(timeout=4500)
            log("clicked via " + how)
            await wait(0.7)
            return {"ok": True, "how": "click:" + how, "target": S.get("target_fp", "")}
        except Exception as e:
            last = how + ": " + str(e)[:120]
            log("miss " + last)
    try:
        if await js_click(fr, S["js_spec"]): log("clicked via js-dispatch"); await wait(0.7); return {"ok": True, "how": "click:js-dispatch", "target": S.get("target_fp", "")}
    except Exception as e: last = "js: " + str(e)[:120]; log(last)
    return {"ok": False, "why": last, "how": "click:failed"}

